import React from "react";
import { useNavigate } from "react-router-dom";

function Footer() {
  const navigate = useNavigate();

  return (
    <div style={styles.footer}>
      <p>© 2026 Doctor Booking System</p>

      <button
        style={styles.button}
        onClick={() => navigate("/add-doctor")}
      >
        ➕ Add Doctor
      </button>
    </div>
  );
}

const styles = {
  footer: {
    marginTop: "50px",
    padding: "20px",
    background: "#1976d2",
    color: "#fff",
    textAlign: "center",
  },
  button: {
    marginTop: "10px",
    padding: "10px 15px",
    border: "none",
    borderRadius: "8px",
    background: "#fff",
    color: "#1976d2",
    cursor: "pointer",
    fontWeight: "bold",
  },
};

export default Footer;
